function makePanelsCollapsible(){
 document.querySelectorAll("#app .panel").forEach(panel=>{
  if(panel.dataset.collapsibleReady==="1")return;
  const heading=[...panel.children].find(el=>/^H[1-4]$/.test(el.tagName));
  if(!heading)return;
  panel.dataset.collapsibleReady="1";
  const bar=document.createElement("div");bar.className="panel-titlebar";
  panel.insertBefore(bar,heading);bar.appendChild(heading);
  const toggle=document.createElement("button");toggle.type="button";toggle.className="panel-collapse-toggle";toggle.textContent="−";toggle.setAttribute("aria-label","إخفاء اللوحة");bar.appendChild(toggle);
  const content=document.createElement("div");content.className="panel-collapse-content";
  while(bar.nextSibling)content.appendChild(bar.nextSibling);
  panel.appendChild(content);
  toggle.onclick=()=>{const closed=content.classList.toggle("collapsed");toggle.textContent=closed?"+":"−";toggle.setAttribute("aria-label",closed?"إظهار اللوحة":"إخفاء اللوحة")};
 });
}

function applyLanguage(){
 const en=uiLanguage==="en";
 document.documentElement.lang=en?"en":"ar";
 document.documentElement.dir=en?"ltr":"rtl";
 document.body.style.direction=en?"ltr":"rtl";
 const toggle=$("languageToggle");if(toggle)toggle.textContent=en?"العربية":"English";const dashToggle=$("dashboardLanguage");if(dashToggle)dashToggle.textContent=en?"ع":"E";
 const map=en?englishText:new Map([...englishText].map(([ar,eng])=>[eng,ar]));
 document.querySelectorAll("h1,h2,h3,h4,p,label,button,span,option,small,th,td,strong,div").forEach(el=>{
   if(el.children.length===0){const v=el.textContent; if(map.has(v))el.textContent=map.get(v);}
 });
 document.querySelectorAll("#newRecordForm label").forEach(el=>{if(en){if(el.textContent==="وصف السجل / المشكلة / الإجراء")el.textContent="Record / issue / action description";if(el.textContent==="المسؤول عن المتابعة")el.textContent="Assigned to";if(el.textContent==="التاريخ")el.textContent="Date";if(el.textContent==="الفرع")el.textContent="Branch";if(el.textContent==="نوع التقرير")el.textContent="Report type";if(el.textContent==="الحالة")el.textContent="Status";}else{const back=new Map([...englishText].map(([a,b])=>[b,a]));if(back.has(el.textContent))el.textContent=back.get(el.textContent);}});
}
window.toggleLanguage=function(){uiLanguage=uiLanguage==="ar"?"en":"ar";applyLanguage();};



start();
applyLanguage();
if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./service-worker.js").catch(e=>console.warn("M-Daily install support unavailable",e)));
